//! Measure unseen house and pipe challenges without changing the selected navigator.
#![cfg(feature = "robots")]
#[path = "../examples/robots/flight_control/mod.rs"] mod flight_control;
#[path = "../examples/robots/pursuit/arena.rs"] mod arena;
#[path = "../examples/robots/pursuit/sight.rs"] mod sight;
#[path = "../runs/quality-research/navigation-cover-task.rs"] mod task;
use task::{Task,Route};
use flight_control::FlightPilot;
use bevy_gym::training::{RecurrentPpoConfig,RecurrentPpoPolicy};
#[test]
fn audit_cover(){
 let pilot=FlightPilot::bundled().unwrap();let config=RecurrentPpoConfig{actor_hidden_size:64,critic_hidden_sizes:vec![64,64],..Default::default()};
 let candidate=std::env::var("NAVIGATOR_CANDIDATE").unwrap();
 let policy=RecurrentPpoPolicy::load(&candidate,32,32,1,&[-1.0;4],&[1.0;4],&config).unwrap();let memory=policy.initial_memory();let mut rows=Vec::new();
 for route in [Route::House,Route::Pipe]{for seed in [0,1,2,42,u64::MAX]{
  let mut task=Task::new(seed,route);let mut trace=Vec::new();
  while !task.ended&&task.steps<1500{let action=policy.mean_action(&task.features(),&memory).unwrap().action;task.advance(&action,&pilot);trace.push(task.trace());}
  let mut row=task.result();row["seed"]=seed.into();row["trace"]=trace.into();rows.push(row);
 }}
 println!("COVER_AUDIT={}",serde_json::to_string(&rows).unwrap());
 let arena=arena::Arena::default();let geometry:Vec<_>=arena.blocks().iter().map(|block|serde_json::json!({"centre":block.centre.to_array(),"half":block.half.to_array(),"rotation":block.rotation.to_array(),"surface":format!("{:?}",block.surface)})).collect();println!("ARENA_GEOMETRY={}",serde_json::to_string(&geometry).unwrap());
}

//! Temporary sensor-limited navigation reference in the real blockout collision world.
#![cfg(feature = "robots")]
#[path = "../examples/robots/flight_control/mod.rs"] mod flight_control;
#[path = "../examples/robots/pursuit/arena.rs"] mod arena;
#[path = "../examples/robots/pursuit/sight.rs"] mod sight;
use bevy::math::{Dir2,Dir3,Vec2,Vec3,Quat};
use bevy_gym::{Env,robots::{DroneHover,DroneObstacle,DroneObservation}};
use flight_control::{FlightGoal,FlightPilot};
use arena::{Arena,Movement,layout::Surface};
use sight::{Sight,Contact};
use std::time::Duration;

fn command(observation:DroneObservation,contact:Contact,velocity:Vec3,stand_off:f32,lead:f32,arena:&Arena)->FlightGoal {
 let contact=match contact { Contact::Visible(point)=>Contact::Visible(point+velocity*lead), Contact::Remembered{point,age}=>Contact::Remembered{point:point+velocity*(age.as_secs_f32()+lead),age}, Contact::Unknown=>Contact::Unknown };
 let current=observation.position();
 let forward=observation.orientation()*Vec3::NEG_Z;
 let current_heading=Vec2::new(forward.x,forward.z).normalize_or_zero();
 let (position,direction)=match contact {
  Contact::Visible(point)|Contact::Remembered{point,..}=>{
   let offset=Vec3::new(point.x-current.x,0.0,point.z-current.z);
   let direction=offset.normalize_or_zero();
   let position=Vec3::new(point.x,2.5,point.z)-direction*stand_off;
   (position,Dir2::new(Vec2::new(direction.x,direction.z)).unwrap_or(Dir2::X))
  }
  Contact::Unknown=>{
   let direction=Quat::from_rotation_y(0.5)*Vec3::new(current_heading.x,0.0,current_heading.y);
   (Vec3::new(current.x,2.5,current.z),Dir2::new(Vec2::new(direction.x,direction.z)).unwrap_or(Dir2::X))
  }
 };
 let mut displacement=(position-current).clamp_length_max(3.0);
 for index in 0..8 {
  let angle=index as f32*std::f32::consts::TAU/8.0;
  let direction=Vec3::new(angle.cos(),0.0,angle.sin());
  let distance=[-0.4_f32,0.0,0.4].into_iter().map(|height|{
   let from=current+Vec3::Y*height;
   arena.obstruction(from,from+direction*3.0).unwrap_or(3.0)
  }).fold(3.0_f32,f32::min);
  if distance<2.0 {displacement-=direction*(2.0-distance)*2.0;}
 }
 let position=current+displacement.clamp_length_max(3.0);
 FlightGoal::try_from((position.clamp(Vec3::new(-9.5,1.0,-9.5),Vec3::new(9.5,4.0,9.5)),direction)).unwrap()
}

#[test]
fn measure_sensor_limited_navigation() {
 let pilot=FlightPilot::bundled().unwrap();let mut records=Vec::new();
 for stand_off in [3.0_f32,5.0,7.0] { for lead in [0.0_f32,0.5,1.0] { for route in ["stationary","lateral","approach"] {
  for seed in [42] {
   let mut arena=Arena::default();
   let obstacles=arena.blocks().iter().filter(|b|b.surface!=Surface::Floor).map(|b|DroneObstacle::try_from((b.centre,b.half,b.rotation)).unwrap());
   let mut drone=DroneHover::with_obstacles(obstacles);
   let mut observation=drone.reset(Some(seed)).observation;
   let mut sight=Sight::default();let mut contact=Contact::Unknown;
   let mut velocity=Vec3::ZERO;let mut previous=None;
   let mut goal=command(observation,contact,velocity,stand_off,lead,&arena);let mut completed=0;let mut visible=0;let mut first_seen=None;let mut ended=false;
   let mut right=true;let mut back=false;let mut samples=Vec::new();
   for index in 0..1500 {
    let position=arena.position();
    if position.x>6.0 {right=false;} if position.x < -6.0 {right=true;}
    if position.z<3.0 {back=true;} if position.z>9.0 {back=false;}
    let movement=if index<250 {Movement::Idle} else {match route {"lateral"=>if right {Movement::Right}else{Movement::Left},"approach"=>if back{Movement::Backward}else{Movement::Forward},_=>Movement::Idle}};
    arena.step(movement);
    let orientation=observation.orientation();
    contact=sight.sample(&arena,observation.position()+orientation*Vec3::new(0.0,0.0,-0.22),Dir3::new(orientation*Vec3::NEG_Z).unwrap(),arena.position(),Duration::from_millis(20));
    if let Contact::Visible(point)=contact {
     if let Some(old)=previous { let delta:Vec3=point-old; velocity=Vec3::new(delta.x,0.0,delta.z)/0.02;velocity=velocity.clamp_length_max(4.0); }
     previous=Some(point);visible+=1;first_seen.get_or_insert(index);
    }else{previous=None;}
    if matches!(contact,Contact::Unknown){velocity=Vec3::ZERO;}
    if index%5==0 {goal=command(observation,contact,velocity,stand_off,lead,&arena);}
    let step=drone.step(pilot.action(observation,goal).unwrap());observation=step.observation;completed=index+1;
    if index%10==0 ||step.is_done(){samples.push(serde_json::json!({"time_seconds":completed as f32*0.02,"drone_metres":observation.position().to_array(),"target_metres":arena.position().to_array(),"visible":matches!(contact,Contact::Visible(_))}));}
    if step.is_done(){ended=true;break;}
   }
   records.push(serde_json::json!({"stand_off_metres":stand_off,"lead_seconds":lead,"route":route,"seed":seed,"completed_actions":completed,"ended":ended,"visible_actions":visible,"first_seen_action":first_seen,"samples":samples}));
  }
 }
 }}
 println!("NAVIGATION_PROBE={}",serde_json::to_string(&records).unwrap());
}

//! Native held-out navigation audit, including adversarial motion timing and direction.
#![cfg(feature = "robots")]
#[path = "../examples/robots/flight_control/mod.rs"] mod flight_control;
#[path = "../examples/robots/pursuit/arena.rs"] mod arena;
#[path = "../examples/robots/pursuit/sight.rs"] mod sight;
#[path = "../runs/quality-research/navigation-qualification-task.rs"] mod task;
use task::{Task,Route};
use flight_control::FlightPilot;
use bevy_gym::training::{RecurrentPpoConfig,RecurrentPpoPolicy};
#[test]
fn qualify_navigator(){
 let pilot=FlightPilot::bundled().unwrap();
 let path=std::env::var("NAVIGATOR_CANDIDATE").expect("set the frozen candidate checkpoint path");
 let config=RecurrentPpoConfig{actor_hidden_size:64,critic_hidden_sizes:vec![64,64],..Default::default()};
 let policy=RecurrentPpoPolicy::load(&path,32,32,1,&[-1.0;4],&[1.0;4],&config).unwrap();let memory=policy.initial_memory();let mut rows=Vec::new();
 for (name,route,delay,right) in [("stationary",Route::Stationary,250,true),("lateral",Route::Lateral,250,true),("approach",Route::Approach,250,true),("lateral-immediate-right",Route::Lateral,0,true),("lateral-immediate-left",Route::Lateral,0,false),("approach-immediate",Route::Approach,0,true)]{
  for offset in 2001..=2032{
   let seed=u64::MAX-offset;let mut task=Task::new(seed,route,delay,right);let mut trace=Vec::new();
   while !task.ended&&task.steps<1500{let action=policy.mean_action(&task.features(),&memory).unwrap().action;task.advance(&action,&pilot);if offset==2001{trace.push(task.trace());}}
   let mut row=task.result();row["seed"]=seed.into();row["profile"]=name.into();row["pass"]=(task.steps==1500&&task.visible>=900&&task.first_seen.is_some_and(|step|step<=500)).into();row["trace"]=trace.into();rows.push(row);
  }
 }
 println!("QUALIFICATION={}",serde_json::to_string(&rows).unwrap());
 assert!(rows.iter().all(|row|row["pass"]==true),"every case must survive 30 seconds, see the target within 10 seconds, and retain sight for at least 60 percent of all actions");
}

//! Experimental PPO refinement of a frozen imitation navigator, with Markov actor calls.
#![cfg(feature = "robots")]
#[path = "../examples/robots/flight_control/mod.rs"] mod flight_control;
#[path = "../examples/robots/pursuit/arena.rs"] mod arena;
#[path = "../examples/robots/pursuit/sight.rs"] mod sight;
#[path = "../runs/quality-research/navigation-cover-task.rs"] mod task;
use task::{Task,Route};
use flight_control::FlightPilot;
use bevy_gym::training::{RecurrentPpoAgent,RecurrentPpoPolicy,RecurrentPpoConfig,RecurrentPpoSequence,RecurrentSampler,SeedConfig};
struct Transition{input:Vec<f32>,raw:Vec<f32>,log:f32,value:f32,next:f32,reward:f32,terminal:bool,boundary:bool}
struct Lane{task:Task,sampler:RecurrentSampler,episode:u64}
fn route(index:usize)->Route{match index%5{0=>Route::Stationary,1=>Route::Lateral,2=>Route::Approach,3=>Route::House,_=>Route::Pipe}}
fn evaluate(policy:&RecurrentPpoPolicy,pilot:&FlightPilot)->serde_json::Value{
 let mut rows=Vec::new();let memory=policy.initial_memory();for course in 0..5{for seed in [0,1,2,42,u64::MAX]{
  let mut task=Task::new(seed,route(course));
  while !task.ended&&task.steps<1500{let action=policy.mean_action(&task.features(),&memory).unwrap().action;task.advance(&action,pilot);}
  let mut result=task.result();result["seed"]=seed.into();rows.push(result);
 }}serde_json::json!(rows)
}
#[test]
fn train_cover_navigator(){
 let pilot=FlightPilot::bundled().unwrap();let config=RecurrentPpoConfig{actor_hidden_size:64,critic_hidden_sizes:vec![64,64],actor_learning_rate:0.0001,critic_learning_rate:0.001,minibatch_sequences:64,entropy_coefficient:0.001,initial_log_std:-2.0,log_std_min:-3.0,log_std_max:-2.0,..Default::default()};
 let seeds=SeedConfig::from_root(23);let mut agent=RecurrentPpoAgent::load_actor_with_fresh_critic("runs/quality-research/navigation-ppo/140.mpk",32,32,1,&[-1.0;4],&[1.0;4],config,seeds).unwrap();
 let seed=|lane:usize,episode:u64|(seeds.environment_episode(lane,episode)&(u64::MAX>>1))|(1<<10);
 let mut lanes:Vec<_>=(0..8).map(|index|Lane{task:Task::new(seed(index,0),route(index)),sampler:RecurrentSampler::new(seeds.action.wrapping_add(index as u64)),episode:0}).collect();
 std::fs::create_dir_all("runs/quality-research/navigation-cover-ppo").unwrap();
 println!("INITIAL={}",evaluate(&agent.policy(),&pilot));
 for update in 1..=300{
  let policy=agent.policy();let memory=policy.initial_memory();let mut sequences=Vec::new();
  for (index,lane) in lanes.iter_mut().enumerate(){
   let mut transitions=Vec::new();
   for _ in 0..64{
    let input=lane.task.features();let action=policy.sample_action(&input,&memory,&mut lane.sampler).unwrap();let value=policy.value(&input,0).unwrap();let reward=lane.task.advance(&action.action,&pilot);let next=policy.value(&lane.task.features(),0).unwrap();let terminal=lane.task.ended;let boundary=terminal||lane.task.steps>=1500;
    transitions.push(Transition{input,raw:action.pre_tanh_action,log:action.log_probability,value,next,reward,terminal,boundary});
    if boundary{lane.episode+=1;lane.task=Task::new(seed(index,lane.episode),route(index+lane.episode as usize));}
   }
   let mut advantage=0.0;
   for t in transitions.into_iter().rev(){
    let bootstrap=if t.terminal{0.0}else{1.0};let trace=if t.boundary{0.0}else{1.0};let delta=t.reward+0.99*bootstrap*t.next-t.value;advantage=delta+0.99*0.95*trace*advantage;
    sequences.push(RecurrentPpoSequence{observations:vec![t.input.clone()],global_states:vec![t.input],pre_tanh_actions:vec![t.raw],old_log_probabilities:vec![t.log],advantages:vec![advantage],returns:vec![t.value+advantage],value_index:0,initial_memory:memory.clone()});
   }
  }
  // The actor has no carried memory, so every optimization sequence has one action.
  if update==1{for _ in 0..10{agent.update_critic(&sequences).unwrap();}}
  let metrics=agent.update(&sequences).unwrap();
  if update==1||update%20==0{let policy=agent.policy();let scores=evaluate(&policy,&pilot);println!("UPDATE={update} METRICS={metrics:?} SCORES={scores}");std::fs::write(format!("runs/quality-research/navigation-cover-ppo/{update}.json"),scores.to_string()).unwrap();std::fs::write(format!("runs/quality-research/navigation-cover-ppo/{update}.mpk"),policy.to_bytes().unwrap()).unwrap();}
 }
}

