//! Experimental imitation training; this does not install a gameplay controller.
#![cfg(feature = "robots")]
#[path = "../examples/robots/flight_control/mod.rs"] mod flight_control;
#[path = "../examples/robots/pursuit/arena.rs"] mod arena;
#[path = "../examples/robots/pursuit/sight.rs"] mod sight;
#[path = "../runs/quality-research/navigation-task.rs"] mod task;
use task::{Task,Route};
use flight_control::FlightPilot;
use bevy_gym::training::{RecurrentPpoAgent,RecurrentPpoPolicy,RecurrentPpoConfig,RecurrentBehaviorSample,SeedConfig,SplitMix64};
fn evaluate(policy:Option<&RecurrentPpoPolicy>,pilot:&FlightPilot)->serde_json::Value{
 let mut rows=Vec::new();for route in [Route::Stationary,Route::Lateral,Route::Approach]{for seed in [0,1,2,42,u64::MAX]{
  let mut task=Task::new(seed,route);let memory=policy.map(RecurrentPpoPolicy::initial_memory);
  while !task.ended&&task.steps<1500{let action=policy.map_or_else(||task.teacher(),|p|p.mean_action(&task.features(),memory.as_ref().unwrap()).unwrap().action);task.advance(&action,pilot);}
  let mut result=task.result();result["seed"]=seed.into();rows.push(result);
 }}serde_json::json!(rows)
}
#[test]
fn train_navigator(){
 let pilot=FlightPilot::bundled().unwrap();let config=RecurrentPpoConfig{actor_hidden_size:64,critic_hidden_sizes:vec![64,64],actor_learning_rate:0.001,..Default::default()};
 let seeds=SeedConfig::from_root(7);let mut agent=RecurrentPpoAgent::new(32,32,1,&[-1.0;4],&[1.0;4],config,seeds).unwrap();let mut random=SplitMix64::new(0x4e41564947415445);
 let mut replay=Vec::new();
 println!("TEACHER={}",evaluate(None,&pilot));
 for episode in 0..30{let route=match episode%3{0=>Route::Stationary,1=>Route::Lateral,_=>Route::Approach};let mut task=Task::new((seeds.environment_episode(0,episode)&(u64::MAX>>1))|(1<<10),route);
  while !task.ended&&task.steps<1500{let action=task.teacher();replay.push(RecurrentBehaviorSample{observation:task.features(),action:action.clone()});task.advance(&action,&pilot);}
 }
 std::fs::create_dir_all("runs/quality-research/navigation-imitation").unwrap();
 for update in 1..=500{
  let batch:Vec<_>=(0..512).map(|_|replay[(random.unit_f64()*replay.len() as f64) as usize].clone()).collect();let mut loss=0.0;for _ in 0..4{loss=agent.behavior_clone(&batch).unwrap();}
  if update%10==0{let policy=agent.policy();let memory=policy.initial_memory();let route=match (update/10)%3{0=>Route::Stationary,1=>Route::Lateral,_=>Route::Approach};let mut task=Task::new((seeds.environment_episode(1,1000+update)&(u64::MAX>>1))|(1<<10),route);
   while !task.ended&&task.steps<1500{let input=task.features();replay.push(RecurrentBehaviorSample{observation:input.clone(),action:task.teacher()});let action=policy.mean_action(&input,&memory).unwrap().action;task.advance(&action,&pilot);}
   if replay.len()>30000{replay.drain(..replay.len()-30000);}
  }
  if update==1||update%50==0{let policy=agent.policy();let scores=evaluate(Some(&policy),&pilot);println!("UPDATE={update} LOSS={loss} SCORES={scores}");std::fs::write(format!("runs/quality-research/navigation-imitation/{update}.json"),scores.to_string()).unwrap();std::fs::write(format!("runs/quality-research/navigation-imitation/{update}.mpk"),policy.to_bytes().unwrap()).unwrap();}
 }
}

//! Temporary native measurement of the frozen pilot with explicit moving goals.
#![cfg(feature = "robots")]
#[path = "../examples/robots/flight_control/mod.rs"]
mod flight_control;
use bevy::math::{Dir2, Vec2, Vec3};
use bevy_gym::{robots::DroneHover, Env};
use flight_control::{FlightGoal, FlightPilot};

#[test]
fn measure_moving_goals() {
    let pilot = FlightPilot::bundled().unwrap();
    let mut records = Vec::new();
    for speed in [0.5_f32, 1.0, 2.0, 4.0] {
        for seed in [0, 1, 2, 42, u64::MAX] {
            let mut drone = DroneHover::disturbed();
            let mut observation = drone.reset(Some(seed)).observation;
            let mut distances = Vec::new();
            let mut samples = Vec::new();
            let mut completed = 0;
            let mut ended = false;
            for index in 0..1500 {
                // Radius is three metres, speed is metres/second, and each action lasts 20 ms.
                let time = index as f32 * 0.02;
                let phase = time * speed / 3.0;
                let target = Vec3::new(3.0 * phase.cos(), 2.0, 3.0 * phase.sin());
                let offset = target - observation.position();
                let heading = Dir2::new(Vec2::new(offset.x, offset.z)).unwrap_or(Dir2::X);
                let goal = FlightGoal::try_from((target, heading)).unwrap();
                let step = drone.step(pilot.action(observation, goal).unwrap());
                observation = step.observation;
                completed = index + 1;
                let distance = observation.position().distance(target);
                if index >= 250 { distances.push(distance); }
                if index % 10 == 0 || step.is_done() {
                    samples.push(serde_json::json!({"time_seconds":time+0.02,"drone_metres":observation.position().to_array(),"target_metres":target.to_array(),"distance_metres":distance}));
                }
                if step.is_done() { ended = true; break; }
            }
            let mean = distances.iter().sum::<f32>() / distances.len().max(1) as f32;
            let maximum = distances.iter().copied().fold(0.0_f32,f32::max);
