 let current_heading=Vec2::new(forward.x,forward.z).normalize_or_zero();
 let (position,direction)=match contact {
  Contact::Visible(point)|Contact::Remembered{point,..}=>{
   let offset=Vec3::new(point.x-current.x,0.0,point.z-current.z);
   let direction=offset.normalize_or_zero();
   let position=Vec3::new(point.x,2.5,point.z)-direction*stand_off;
   (position,Dir2::new(Vec2::new(direction.x,direction.z)).unwrap_or(Dir2::X))
  }
  Contact::Unknown=>{
   let direction=Quat::from_rotation_y(0.5)*Vec3::new(current_heading.x,0.0,current_heading.y);
   (Vec3::new(current.x,2.5,current.z),Dir2::new(Vec2::new(direction.x,direction.z)).unwrap_or(Dir2::X))
  }
 };
 FlightGoal::try_from((position.clamp(Vec3::new(-9.5,1.0,-9.5),Vec3::new(9.5,4.0,9.5)),direction)).unwrap()
}

